function validate([parents]) {
  if (!Array.isArray(parents) || parents.length < 2 || parents.length > 100000) return 'parents needs 2 to 10^5 entries.';
  const n = parents.length;
  if (parents[0] !== -1) return 'parents[0] must be -1 (node 0 is the root).';
  const children = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    const p = parents[i];
    if (!Number.isInteger(p) || p < 0 || p >= n || p === i) return 'Each parents[i] (i > 0) is another node from 0 to n - 1.';
    children[p].push(i);
    if (children[p].length > 2) return 'Each node has at most two children in a binary tree.';
  }
  const stack = [0];
  let reached = 0;
  while (stack.length) {
    const node = stack.pop();
    reached++;
    for (const child of children[node]) stack.push(child);
  }
  if (reached !== n) return 'Every node must hang below node 0 (no cycles).';
  return null;
}

