function countHighestScoreNodes(parents) {
  const n = parents.length;
  const children = Array.from({ length: n }, () => []);
  for (let node = 1; node < n; node++) {
    children[parents[node]].push(node);
  }
  let bestScore = 0;
  let count = 0;

  const dfs = (node) => {
    let size = 1;
    let score = 1;
    for (const child of children[node]) {
      const childSize = dfs(child);
      size += childSize;
      score *= childSize;
    }
    if (node !== 0) {
      score *= n - size;
    }
    if (score > bestScore) {
      bestScore = score;
      count = 1;
    } else if (score === bestScore) {
      count++;
    }
    return size;
  };

  dfs(0);
  return count;
}

