function countHighestScoreNodes(parents) {
  const n = parents.length;
  const neighbours = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    neighbours[i].push(parents[i]);
    neighbours[parents[i]].push(i);
  }
  const scores = [];
  for (let removed = 0; removed < n; removed++) {
    const seen = new Array(n).fill(false);
    seen[removed] = true;
    let score = 1;
    for (const start of neighbours[removed]) {
      let pieceSize = 0;
      const queue = [start];
      seen[start] = true;
      while (queue.length) {
        const current = queue.pop();
        pieceSize++;
        for (const next of neighbours[current]) {
          if (!seen[next]) {
            seen[next] = true;
            queue.push(next);
          }
        }
      }
      score *= pieceSize;
    }
    scores.push(score);
  }
  const top = Math.max(...scores);
  return scores.filter(s => s === top).length;
}

