function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? int(1500, 2000) : int(2, 9);
  const labels = Array.from({ length: n - 1 }, (_, i) => i + 1);
  for (let i = labels.length - 1; i > 0; i--) {
    const j = int(0, i);
    [labels[i], labels[j]] = [labels[j], labels[i]];
  }
  const parents = new Array(n).fill(-1);
  const childCount = new Array(n).fill(0);
  const open = [0];
  const shape = int(0, 3);
  let head = 0;
  for (const label of labels) {
    let index;
    if (shape === 0) index = open.length - 1;
    else if (shape === 1) index = head;
    else if (shape === 2) index = Math.max(0, open.length - 1 - int(0, 2));
    else index = int(0, open.length - 1);
    if (index < head) index = head;
    const parent = open[index];
    parents[label] = parent;
    childCount[parent]++;
    if (childCount[parent] === 2) {
      open[index] = open[head];
      open[head] = parent;
      head++;
    }
    open.push(label);
  }
  return [parents];
}
